let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"e13fff7c7dd2d16c\" body=\"Additional components that you can use:\">\n  Additional components that you can use:\n</FeedbackBlock>\n\n<DocsCategory />\n\nMDX Components [#mdx-components]\n\n<FeedbackBlock id=\"d698132852d23114\" body=\"The default MDX components include Cards, Callouts, Code Blocks and Headings.\">\n  The default MDX components include Cards, Callouts, Code Blocks and Headings.\n</FeedbackBlock>\n\n```ts\nimport defaultMdxComponents from 'fumadocs-ui/mdx';\n```\n\nRelative Link [#relative-link]\n\n<Callout type=\"warn\">\n  Server Component only.\n</Callout>\n\n<FeedbackBlock id=\"33b0634b6705b14a\" body=\"To support links with relative file path in href, override the default a component with:\">\n  To support links with relative file path in `href`, override the default `a` component with:\n</FeedbackBlock>\n\n```tsx title=\"app/docs/[[...slug]]/page.tsx\"\nimport { createRelativeLink } from 'fumadocs-ui/mdx';\nimport { source } from '@/lib/source';\nimport { getMDXComponents } from '@/mdx-components';\n\nconst page = source.getPage(['...']);\n\nreturn (\n  <MdxContent\n    components={getMDXComponents({\n      // override the `a` tag\n      a: createRelativeLink(source, page),\n    })}\n  />\n);\n```\n\n```mdx\n[My Link](./file.mdx)\n```\n\n<FeedbackBlock id=\"a40054d578ca36e4\" body=\"Example: ../../(integrations)/feedback.mdx\">\n  Example: [`../../(integrations)/feedback.mdx`](../../\\(integrations\\)/feedback.mdx)\n</FeedbackBlock>\n";
